actions.script:
try {
    success = true

    // 查询用户的项目列表
    def projectList = ec.entity.find("novel.anime.Project")
        .condition("userId", userId ?: "EX_JOHN_DOE")
        .orderBy("createdDate DESC")
        .disableAuthz()
        .list()

    // 转换为前端需要的格式
    projects = []
    projectList.each { project ->
        projects.add([
            projectId: project.projectId,
            id: project.projectId,
            name: project.name,
            description: project.description,
            status: project.status,
            userId: project.userId,
            createdDate: project.createdDate?.getTime() ?: System.currentTimeMillis(),
            updatedDate: project.lastUpdated?.getTime() ?: System.currentTimeMillis()
        ])
    }

    ec.logger.info("Found ${projects.size()} projects for user ${userId}")
} catch (Exception e) {
    ec.logger.error("Failed to get projects: ${e.message}", e)
    success = false
    projects = []
}

try { success = true message = "项目创建成功"
// 确保有userId def effectiveUserId = userId ?: "EX_JOHN_DOE"
// 创建项目实体 def newProject = ec.entity.makeValue("novel.anime.Project") .setFields([ name: name, description: description ?: "", userId: effectiveUserId, status: "active", createdDate: ec.user.nowTimestamp, lastUpdated: ec.user.nowTimestamp ], true, null, false) .setSequencedIdPrimary() .create()
def projectId = newProject.projectId
ec.logger.info("Project created: ${projectId} for user ${effectiveUserId}")
// 返回项目数据 project = [ projectId: projectId, id: projectId, name: name, description: description ?: "", status: "active", userId: effectiveUserId, createdDate: newProject.createdDate?.getTime() ?: System.currentTimeMillis(), updatedDate: newProject.lastUpdated?.getTime() ?: System.currentTimeMillis() ] } catch (Exception e) { ec.logger.error("Failed to create project: ${e.message}", e) success = false message = "项目创建失败: ${e.message}" project = null }

try {
    success = true

    // 查询项目
    def projectEntity = ec.entity.find("novel.anime.Project")
        .condition("projectId", projectId)
        .disableAuthz()
        .one()

    if (projectEntity) {
        project = [
            projectId: projectEntity.projectId,
            id: projectEntity.projectId,
            name: projectEntity.name,
            description: projectEntity.description,
            status: projectEntity.status,
            userId: projectEntity.userId,
            createdDate: projectEntity.createdDate?.getTime() ?: System.currentTimeMillis(),
            updatedDate: projectEntity.lastUpdated?.getTime() ?: System.currentTimeMillis()
        ]
        message = "项目获取成功"
        ec.logger.info("Project retrieved: ${projectId}")
    } else {
        success = false
        project = null
        message = "项目不存在"
        ec.logger.warn("Project not found: ${projectId}")
    }
} catch (Exception e) {
    ec.logger.error("Failed to get project: ${e.message}", e)
    success = false
    project = null
    message = "项目获取失败: ${e.message}"
}

try {
    // 禁用权限检查
    ec.artifactExecution.disableAuthz()

    // 查询项目
    def projectEntity = ec.entity.find("novel.anime.Project")
        .condition("projectId", projectId)
        .one()

    if (!projectEntity) {
        success = false
        message = "项目不存在"
        return
    }

    // 更新字段
    if (name) projectEntity.name = name
    if (description != null) projectEntity.description = description
    if (status) projectEntity.status = status
    projectEntity.lastUpdated = ec.user.nowTimestamp
    projectEntity.update()

    success = true
    message = "项目更新成功"
    ec.logger.info("Project updated: ${projectId}")
} catch (Exception e) {
    ec.logger.error("Failed to update project: ${e.message}", e)
    success = false
    message = "项目更新失败: ${e.message}"
} finally {
    // 恢复权限检查
    ec.artifactExecution.enableAuthz()
}

try {
    // 查询项目
    def projectEntity = ec.entity.find("novel.anime.Project")
        .condition("projectId", projectId)
        .disableAuthz()
        .one()

    if (!projectEntity) {
        success = false
        message = "项目不存在"
        return
    }

    // 软删除：更新状态为deleted
    projectEntity.status = "deleted"
    projectEntity.lastUpdated = ec.user.nowTimestamp
    projectEntity.update()

    success = true
    message = "项目删除成功"
    ec.logger.info("Project soft deleted: ${projectId}")
} catch (Exception e) {
    ec.logger.error("Failed to delete project: ${e.message}", e)
    success = false
    message = "项目删除失败: ${e.message}"
}

success = true message = "小说导入成功"
// 生成小说ID def novelId = "novel_" + System.currentTimeMillis()
novel = [ novelId: novelId, id: novelId, title: title, projectId: projectId, status: "imported", wordCount: content?.length() ?: 0, author: "未知作者", chapters: [], createdDate: new Date(), updatedDate: new Date() ]

success = true message = "角色列表获取成功"
// 模拟角色数据 characters = [ [ characterId: "char_1", novelId: novelId, name: "主角", role: "protagonist", description: "故事的主人公，勇敢而善良，拥有坚定的意志和正义感", appearance: "身材高大，黑色短发，深邃的眼神", personality: "勇敢、善良、坚定、有正义感", mentionCount: 25, extractionConfidence: 0.95, isLocked: false, createdDate: new Date(), relationships: [ [ relatedCharacterId: "char_2", relatedCharacterName: "反派", relationshipType: "敌对", description: "主要对手，代表邪恶势力" ], [ relatedCharacterId: "char_3", relatedCharacterName: "配角", relationshipType: "朋友", description: "忠实的伙伴和支持者" ] ] ], [ characterId: "char_2", novelId: novelId, name: "反派", role: "antagonist", description: "故事的反面角色，狡猾而强大，是主角的主要对手", appearance: "身材修长，银色长发，冷酷的表情", personality: "狡猾、冷酷、野心勃勃、不择手段", mentionCount: 15, extractionConfidence: 0.88, isLocked: false, createdDate: new Date(), relationships: [ [ relatedCharacterId: "char_1", relatedCharacterName: "主角", relationshipType: "敌对", description: "主要敌人，代表正义势力" ] ] ], [ characterId: "char_3", novelId: novelId, name: "配角", role: "supporting", description: "主角的朋友，提供帮助和支持", appearance: "中等身材，棕色头发，友善的笑容", personality: "忠诚、友善、乐观、可靠", mentionCount: 10, extractionConfidence: 0.75, isLocked: false, createdDate: new Date(), relationships: [ [ relatedCharacterId: "char_1", relatedCharacterName: "主角", relationshipType: "朋友", description: "忠实的朋友和支持者" ] ] ] ]
// 应用过滤器 if (role) { characters = characters.findAll { it.role == role } } if (isLocked != null) { def locked = isLocked == "true" || isLocked == "Y" characters = characters.findAll { it.isLocked == locked } } if (minMentionCount) { characters = characters.findAll { it.mentionCount >= minMentionCount } }
totalCount = characters.size()

success = true message = "文件导入成功" creditsUsed = 5
def novelId = "novel_" + System.currentTimeMillis()
novel = [ novelId: novelId, id: novelId, title: title ?: fileName, author: author ?: "未知作者", projectId: projectId, status: "imported", wordCount: 45000, createdDate: new Date(), updatedDate: new Date() ]

success = true message = "剧集列表获取成功"
episodes = [ [ episodeId: "ep_1", novelId: novelId, episodeNumber: 1, title: "第一集 开端", summary: "故事的开始，介绍主要角色和背景", duration: 25, status: "generated", sceneCount: 3, createdDate: new Date() ], [ episodeId: "ep_2", novelId: novelId, episodeNumber: 2, title: "第二集 冲突", summary: "主要冲突的展开", duration: 28, status: "reviewed", sceneCount: 4, createdDate: new Date() ] ]
totalCount = episodes.size() totalDuration = episodes.sum { it.duration }

success = true message = "处理管道创建成功"
def pipelineId = "pipeline_" + System.currentTimeMillis()
pipeline = [ pipelineId: pipelineId, novelId: novelId, status: "created", currentStage: "structure_analysis", totalStages: 5, completedStages: 0, creditsReserved: 100, creditsUsed: 0, estimatedDuration: 300, createdDate: new Date() ]
